INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_045_M5_S2', 'phasors', '2', 'phasors: Complex-number representations of sinusoidal voltages and currents used for steady-state AC analysis. In Synchronous Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of phasors within Electrical Machines, particularly where the Synchronous Machines module establishes its technical context.', 'SSD_COURSE_045_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M5_S3', 'synchronous impedance', '3', 'synchronous impedance: Equivalent impedance used to represent voltage drops associated with resistance and synchronous reactance in a synchronous machine. In Synchronous Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of synchronous impedance within Electrical Machines, particularly where the Synchronous Machines module establishes its technical context.', 'SSD_COURSE_045_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M5_S4', 'power-angle relation', '4', 'power-angle relation refers to the relationship between electrical power transfer and the torque or power angle of a synchronous machine, subject to its operating model and network conditions. In Synchronous Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of power-angle relation within Electrical Machines, particularly where the Synchronous Machines module establishes its technical context.', 'SSD_COURSE_045_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M5_S5', 'excitation', '5', 'excitation refers to the magnetic-field-producing current or system used to establish machine flux. In Synchronous Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of excitation within Electrical Machines, particularly where the Synchronous Machines module establishes its technical context.', 'SSD_COURSE_045_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M6_S1', 'loss segregation', '1', 'loss segregation: Separating total machine losses into components such as copper, core, mechanical, and stray losses. In Machine Performance and Testing, the focus is on the analysis, design, implementation, interpretation, or evaluation of loss segregation within Electrical Machines, particularly where the Machine Performance and Testing module establishes its technical context.', 'SSD_COURSE_045_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M6_S2', 'efficiency', '2', 'efficiency: Ratio or other defined measure of useful output to input for a process, device, or system under specified operating conditions. In Machine Performance and Testing, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_045_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M6_S3', 'temperature rise', '3', 'temperature rise: Increase in machine temperature above ambient caused by internal losses under specified operating conditions. In Machine Performance and Testing, the focus is on the analysis, design, implementation, interpretation, or evaluation of temperature rise within Electrical Machines, particularly where the Machine Performance and Testing module establishes its technical context.', 'SSD_COURSE_045_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M6_S4', 'load tests', '4', 'load tests: Tests performed while a machine supplies or receives load to determine performance under operating conditions. In Machine Performance and Testing, the focus is on the analysis, design, implementation, interpretation, or evaluation of load tests within Electrical Machines, particularly where the Machine Performance and Testing module establishes its technical context.', 'SSD_COURSE_045_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M6_S5', 'condition assessment', '5', 'condition assessment refers to a systematic method for examining condition assessment using relevant evidence, variables, assumptions, and criteria to support analysis or decision-making. In Machine Performance and Testing, the focus is on the analysis, design, implementation, interpretation, or evaluation of condition assessment within Electrical Machines, particularly where the Machine Performance and Testing module establishes its technical context.', 'SSD_COURSE_045_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M7_S1', 'motor selection', '1', 'motor selection refers to the process of choosing among alternatives for motor selection using defined performance, service, design, and constraint criteria. In Machine Applications and Drives, the focus is on the analysis, design, implementation, interpretation, or evaluation of motor selection within Electrical Machines, particularly where the Machine Applications and Drives module establishes its technical context.', 'SSD_COURSE_045_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M7_S2', 'braking', '2', 'braking: Methods of producing opposing torque to slow or stop an electric motor. In Machine Applications and Drives, the focus is on the analysis, design, implementation, interpretation, or evaluation of braking within Electrical Machines, particularly where the Machine Applications and Drives module establishes its technical context.', 'SSD_COURSE_045_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M7_S3', 'variable-speed drives', '3', 'variable-speed drives: Power-electronic or electromechanical systems that control motor speed and torque. In Machine Applications and Drives, the focus is on the analysis, design, implementation, interpretation, or evaluation of variable-speed drives within Electrical Machines, particularly where the Machine Applications and Drives module establishes its technical context.', 'SSD_COURSE_045_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M7_S4', 'duty cycles', '4', 'duty cycles: Specified patterns of operating time, load, speed, and rest periods used to rate machine operation. In Machine Applications and Drives, the focus is on the analysis, design, implementation, interpretation, or evaluation of duty cycles within Electrical Machines, particularly where the Machine Applications and Drives module establishes its technical context.', 'SSD_COURSE_045_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M7_S5', 'protection', '5', 'protection: Protective functions and devices that detect abnormal electrical conditions and isolate affected equipment or circuits to limit damage and maintain system security. In Machine Applications and Drives, the focus is on the analysis, design, implementation, interpretation, or evaluation of protection within Electrical Machines, particularly where the Machine Applications and Drives module establishes its technical context.', 'SSD_COURSE_045_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M1_S1', 'generators', '1', 'generators: Machines that convert mechanical energy into electrical energy through electromagnetic induction and supply electrical loads or power-system networks. In Power-System Components and Models, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_046_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M1_S2', 'transformers', '2', 'transformers: Static electrical devices that transfer AC power between circuits at different voltage or current levels through electromagnetic induction. In Power-System Components and Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of transformers within Power Systems, particularly where the Power-System Components and Models module establishes its technical context.', 'SSD_COURSE_046_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M1_S3', 'lines', '3', 'lines: Transmission or distribution conductors and associated parameters used to carry electrical power between network buses. In Power-System Components and Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of lines within Power Systems, particularly where the Power-System Components and Models module establishes its technical context.', 'SSD_COURSE_046_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M1_S4', 'cables', '4', 'cables: Insulated electrical conductors designed to carry power with defined thermal, dielectric, and mechanical limits. In Power-System Components and Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of cables within Power Systems, particularly where the Power-System Components and Models module establishes its technical context.', 'SSD_COURSE_046_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M1_S5', 'loads', '5', 'loads: Electrical devices or aggregated demand that consume real and reactive power from a power system. In Power-System Components and Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of loads within Power Systems, particularly where the Power-System Components and Models module establishes its technical context.', 'SSD_COURSE_046_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M1_S6', 'per-unit system', '6', 'per-unit system refers to a normalised representation of electrical quantities using selected base values to simplify power-system calculations. In Power-System Components and Models, the focus is on the analysis, design, implementation, interpretation, or evaluation of per-unit system within Power Systems, particularly where the Power-System Components and Models module establishes its technical context.', 'SSD_COURSE_046_M1_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M2_S1', 'line parameters', '1', 'line parameters: Electrical parameters such as resistance, inductance, capacitance, and conductance used to model transmission lines. In Transmission and Distribution, the focus is on the analysis, design, implementation, interpretation, or evaluation of line parameters within Power Systems, particularly where the Transmission and Distribution module establishes its technical context.', 'SSD_COURSE_046_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M2_S2', 'voltage regulation', '2', 'voltage regulation: Rules and compliance mechanisms used to govern voltage regulation within the applicable disciplinary or legal framework. In Transmission and Distribution, the focus is on the analysis, design, implementation, interpretation, or evaluation of voltage regulation within Power Systems, particularly where the Transmission and Distribution module establishes its technical context.', 'SSD_COURSE_046_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M2_S3', 'distribution feeders', '3', 'distribution feeders: Circuits that deliver electrical power from substations to downstream consumers. In Transmission and Distribution, the focus is on the analysis, design, implementation, interpretation, or evaluation of distribution feeders within Power Systems, particularly where the Transmission and Distribution module establishes its technical context.', 'SSD_COURSE_046_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M2_S4', 'network topology', '4', 'network topology refers to the connectivity and arrangement of buses, lines, transformers, switches, and other power-system elements. In Transmission and Distribution, the focus is on the analysis, design, implementation, interpretation, or evaluation of network topology within Power Systems, particularly where the Transmission and Distribution module establishes its technical context.', 'SSD_COURSE_046_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M3_S1', 'bus types', '1', 'bus types: Power-flow bus classifications such as slack, PV, and PQ buses defined by specified and unknown electrical quantities. In Power-Flow Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of bus types within Power Systems, particularly where the Power-Flow Analysis module establishes its technical context.', 'SSD_COURSE_046_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M3_S2', 'admittance matrix', '2', 'admittance matrix: Matrix representation of network current-voltage relationships used in power-flow and other system analyses. In Power-Flow Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of admittance matrix within Power Systems, particularly where the Power-Flow Analysis module establishes its technical context.', 'SSD_COURSE_046_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M3_S3', 'Gauss-Seidel', '3', 'Gauss-Seidel refers to an iterative numerical method used to solve power-flow equations. In Power-Flow Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of Gauss-Seidel within Power Systems, particularly where the Power-Flow Analysis module establishes its technical context.', 'SSD_COURSE_046_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M3_S4', 'Newton-Raphson', '4', 'Newton-Raphson refers to a nonlinear iterative method widely used to solve power-flow equations with rapid local convergence. In Power-Flow Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of Newton-Raphson within Power Systems, particularly where the Power-Flow Analysis module establishes its technical context.', 'SSD_COURSE_046_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M3_S5', 'fast decoupled methods', '5', 'fast decoupled methods: Power-flow solution methods that exploit approximate decoupling between active-power/angle and reactive-power/voltage relationships. In Power-Flow Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of fast decoupled methods within Power Systems, particularly where the Power-Flow Analysis module establishes its technical context.', 'SSD_COURSE_046_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M4_S1', 'symmetrical components', '1', 'symmetrical components: Transformation of unbalanced three-phase quantities into positive-, negative-, and zero-sequence components. In Fault Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of symmetrical components within Power Systems, particularly where the Fault Analysis module establishes its technical context.', 'SSD_COURSE_046_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M4_S2', 'balanced faults', '2', 'balanced faults: Three-phase power-system faults in which the phase quantities remain symmetrical and can be analysed using a balanced positive-sequence model. In Fault Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of balanced faults within Power Systems, particularly where the Fault Analysis module establishes its technical context.', 'SSD_COURSE_046_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M4_S3', 'unbalanced faults', '3', 'unbalanced faults: Faults that disturb phase symmetry, such as single-line-to-ground, line-to-line, or double-line-to-ground faults. In Fault Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of unbalanced faults within Power Systems, particularly where the Fault Analysis module establishes its technical context.', 'SSD_COURSE_046_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M4_S4', 'short-circuit levels', '4', 'short-circuit levels: Calculated fault currents or fault power used to assess equipment duty and protection requirements. In Fault Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of short-circuit levels within Power Systems, particularly where the Fault Analysis module establishes its technical context.', 'SSD_COURSE_046_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M5_S1', 'relays', '1', 'relays: Protective devices that detect abnormal electrical conditions and initiate circuit-breaker operation. In Protection Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of relays within Power Systems, particularly where the Protection Systems module establishes its technical context.', 'SSD_COURSE_046_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M5_S2', 'overcurrent protection', '2', 'overcurrent protection: Protection that detects current above a specified pickup or characteristic and trips equipment according to defined time-current behaviour. In Protection Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of overcurrent protection within Power Systems, particularly where the Protection Systems module establishes its technical context.', 'SSD_COURSE_046_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M5_S3', 'distance protection', '3', 'distance protection: Relay protection that estimates the apparent impedance to a fault and operates when the measured impedance falls within defined protection zones. In Protection Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of distance protection within Power Systems, particularly where the Protection Systems module establishes its technical context.', 'SSD_COURSE_046_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M5_S4', 'differential protection', '4', 'differential protection: Protection that compares currents entering and leaving a protected zone and operates when their difference exceeds the defined restraint or operating condition. In Protection Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of differential protection within Power Systems, particularly where the Protection Systems module establishes its technical context.', 'SSD_COURSE_046_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M5_S5', 'coordination', '5', 'coordination: Selection and setting of protective devices so faults are cleared selectively while maintaining required system continuity. In Protection Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of coordination within Power Systems, particularly where the Protection Systems module establishes its technical context.', 'SSD_COURSE_046_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M6_S1', 'transient stability', '1', 'transient stability: Ability of a power system to maintain synchronism after a large disturbance. In Power-System Stability, the focus is on the analysis, design, implementation, interpretation, or evaluation of transient stability within Power Systems, particularly where the Power-System Stability module establishes its technical context.', 'SSD_COURSE_046_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M6_S2', 'small-signal stability', '2', 'small-signal stability refers to the ability of a power system to maintain synchronism following small disturbances, assessed from the behaviour of its linearized dynamic model. In Power-System Stability, the focus is on the analysis, design, implementation, interpretation, or evaluation of small-signal stability within Power Systems, particularly where the Power-System Stability module establishes its technical context.', 'SSD_COURSE_046_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M6_S3', 'rotor angle', '3', 'rotor angle refers to the electrical angle describing the position of a synchronous-machine rotor relative to the rotating system field. In Power-System Stability, the focus is on the analysis, design, implementation, interpretation, or evaluation of rotor angle within Power Systems, particularly where the Power-System Stability module establishes its technical context.', 'SSD_COURSE_046_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M6_S4', 'voltage stability', '4', 'voltage stability: Ability of a power system to maintain acceptable bus voltages after changes or disturbances in operating conditions. In Power-System Stability, the focus is on the analysis, design, implementation, interpretation, or evaluation of voltage stability within Power Systems, particularly where the Power-System Stability module establishes its technical context.', 'SSD_COURSE_046_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M7_S1', 'economic dispatch', '1', 'economic dispatch: Allocation of generation output among available units to meet demand at minimum operating cost subject to constraints. In System Operation and Emerging Grids, the focus is on the analysis, design, implementation, interpretation, or evaluation of economic dispatch within Power Systems, particularly where the System Operation and Emerging Grids module establishes its technical context.', 'SSD_COURSE_046_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M7_S2', 'state estimation', '2', 'state estimation: Estimation of system voltage states from measurements and network models. In System Operation and Emerging Grids, the focus is on the analysis, design, implementation, interpretation, or evaluation of state estimation within Power Systems, particularly where the System Operation and Emerging Grids module establishes its technical context.', 'SSD_COURSE_046_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M7_S3', 'Supervisory Control and Data Acquisition / Energy Management System (SCADA/EMS)', '3', 'SCADA/EMS: Supervisory Control and Data Acquisition and Energy Management System functions used to monitor and operate power networks. In System Operation and Emerging Grids, the focus is on the analysis, design, implementation, interpretation, or evaluation of SCADA/EMS within Power Systems, particularly where the System Operation and Emerging Grids module establishes its technical context.', 'SSD_COURSE_046_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M7_S4', 'distributed generation', '4', 'distributed generation: Electric generation connected near loads or within distribution networks rather than only at central generating stations. In System Operation and Emerging Grids, the focus is on the analysis, design, implementation, interpretation, or evaluation of distributed generation within Power Systems, particularly where the System Operation and Emerging Grids module establishes its technical context.', 'SSD_COURSE_046_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_046_M7_S5', 'microgrids', '5', 'microgrids: Locally bounded electrical systems containing loads and distributed resources that can operate connected to or separated from a main grid. In System Operation and Emerging Grids, the focus is on the analysis, design, implementation, interpretation, or evaluation of microgrids within Power Systems, particularly where the System Operation and Emerging Grids module establishes its technical context.', 'SSD_COURSE_046_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M1_S1', 'diodes', '1', 'diodes: Semiconductor devices that primarily conduct current in one direction and block it in the opposite direction. In Power Semiconductor Devices, the focus is on the analysis, design, implementation, interpretation, or evaluation of diodes within Power Electronics, particularly where the Power Semiconductor Devices module establishes its technical context.', 'SSD_COURSE_047_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M1_S2', 'thyristors', '2', 'thyristors: Controlled semiconductor switches that latch into conduction after triggering and turn off when current conditions permit. In Power Semiconductor Devices, the focus is on the analysis, design, implementation, interpretation, or evaluation of thyristors within Power Electronics, particularly where the Power Semiconductor Devices module establishes its technical context.', 'SSD_COURSE_047_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_047_M1_S3', 'MOSFETs', '3', 'MOSFETs: Voltage-controlled semiconductor switches with low gate-drive power and fast switching capability. In Power Semiconductor Devices, the focus is on the analysis, design, implementation, interpretation, or evaluation of MOSFETs within Power Electronics, particularly where the Power Semiconductor Devices module establishes its technical context.', 'SSD_COURSE_047_M1_S3', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;